{
  "hechos": [
    {"id": "H1", "texto": "La Alcaldía de Santa Brígida canceló la edición de este año del Festival de la Cosecha.", "tipo": "dato", "paginas": ["P1", "P2", "P3", "P4", "P5", "P6"]},
    {"id": "H2", "texto": "La decisión se debe a una plaga de gusano cogollero que afectó los cultivos de maíz.", "tipo": "dato", "paginas": ["P1", "P2", "P3", "P4", "P5", "P6"]},
    {"id": "H3", "texto": "Las pérdidas llegarían al 60 % del maíz sembrado en el municipio.", "tipo": "dato", "paginas": ["P1", "P2", "P3", "P4", "P5", "P6"]},
    {"id": "H4", "texto": "Al evento llegaban cerca de 25.000 turistas cada año.", "tipo": "dato", "paginas": ["P1", "P2", "P3", "P4", "P5", "P6"]},
    {"id": "H5", "texto": "Wilson Lozano, docente del barrio San José, contó a InfoExprés que en su vereda no quedó una sola mazorca sana.", "tipo": "dato", "paginas": ["P1"]},
    {"id": "H6", "texto": "En la vereda La Pradera, la asociación de productores contó 229 hectáreas afectadas.", "tipo": "dato", "paginas": ["P3"]},
    {"id": "H7", "texto": "Wilson Patiño, habitante del barrio Las Acacias, contó a Noticias al Instante que los hoteles empezaron a recibir cancelaciones.", "tipo": "dato", "paginas": ["P3"]},
    {"id": "H8", "texto": "Sandra Rincón, comerciante del barrio El Carmen, contó a El Dato Viral que los hoteles empezaron a recibir cancelaciones.", "tipo": "dato", "paginas": ["P5"]},
    {"id": "H9", "texto": "Sandra Toro, integrante de la junta comunal del barrio Villa Nueva, contó a Alerta Nacional Ya que en su vereda no quedó una sola mazorca sana.", "tipo": "dato", "paginas": ["P6"]}
  ]
}
